// Small shared pieces for the Feedbax dialog. Built only from the host's own shadcn primitives.
import * as React from "react";
import { LoaderCircle } from "lucide-react";

import { Button, buttonVariants } from "@/components/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

/** Per-radius CSS variables so custom surfaces follow whatever corner style the host's dialog uses. */
export const RADIUS_VARS = { "--fbx-r": "0px", "--fbx-r-sm": "0px" } as React.CSSProperties;
export const R = "rounded-[var(--fbx-r)]";
export const R_SM = "rounded-[var(--fbx-r-sm)]";

/** Reads the host dialog's corner radius once, so cards and thumbnails match the host's style. */
export function useHostRadius(ref: React.RefObject<HTMLElement | null>) {
  React.useLayoutEffect(() => {
    const el = ref.current;
    const host = el?.parentElement;
    if (!el || !host) return;
    const radius = getComputedStyle(host).borderTopLeftRadius || "0px";
    el.style.setProperty("--fbx-r", radius);
    el.style.setProperty("--fbx-r-sm", `calc(${radius} * 0.75)`);
  }, [ref]);
}

export function Spinner({ className }: { className?: string }) {
  return <LoaderCircle aria-hidden className={cn("size-4 animate-spin", className)} />;
}

export function useIsMac(): boolean {
  const [mac, setMac] = React.useState(false);
  React.useEffect(() => {
    setMac(/Mac|iPhone|iPad/i.test(navigator.platform || navigator.userAgent));
  }, []);
  return mac;
}

export function Kbd({ children }: { children: React.ReactNode }) {
  return (
    <kbd
      data-slot="kbd"
      className="pointer-events-none inline-flex h-4 min-w-4 items-center justify-center rounded-[2px] border border-current/30 px-1 font-sans text-[10px] leading-none font-medium opacity-80 select-none"
    >
      {children}
    </kbd>
  );
}

type IconTipProps = Omit<React.ComponentProps<"button">, "children"> & {
  label: string;
  shortcut?: string;
  variant?: React.ComponentProps<typeof Button>["variant"];
  size?: React.ComponentProps<typeof Button>["size"];
  children: React.ReactNode;
};

/** A button with an accessible name and a tooltip (label + keyboard shortcut). */
export function IconTip({
  label,
  shortcut,
  variant = "ghost",
  size = "icon",
  className,
  children,
  ...props
}: IconTipProps) {
  return (
    <Tooltip>
      <TooltipTrigger
        type="button"
        aria-label={label}
        aria-keyshortcuts={shortcut}
        className={cn(buttonVariants({ variant, size }), className)}
        {...(props as object)}
      >
        {children}
      </TooltipTrigger>
      <TooltipContent>
        {label}
        {shortcut ? <Kbd>{shortcut}</Kbd> : null}
      </TooltipContent>
    </Tooltip>
  );
}

/** Roving-tabindex helper for radio-style groups (arrow keys move and select). */
export function useRoving(count: number, selected: number, onSelect: (index: number) => void) {
  return (index: number) => ({
    tabIndex: (selected < 0 ? index === 0 : index === selected) ? 0 : -1,
    onKeyDown: (event: React.KeyboardEvent<HTMLElement>) => {
      const keys: Record<string, number> = {
        ArrowRight: index + 1,
        ArrowDown: index + 1,
        ArrowLeft: index - 1,
        ArrowUp: index - 1,
        Home: 0,
        End: count - 1,
      };
      if (!(event.key in keys)) return;
      event.preventDefault();
      event.stopPropagation();
      const next = (keys[event.key] + count) % count;
      onSelect(next);
      const group = event.currentTarget.closest("[role='radiogroup']");
      group?.querySelectorAll<HTMLElement>("[role='radio']")[next]?.focus();
    },
  });
}

type ConfirmProps = {
  title: string;
  description: string;
  confirmLabel: string;
  cancelLabel?: string;
  destructive?: boolean;
  onConfirm: () => void;
  onCancel: () => void;
};

/** An in-dialog confirmation (no second modal). Focus starts on the safe choice; Escape cancels. */
export function ConfirmBar({
  title,
  description,
  confirmLabel,
  cancelLabel = "Keep editing",
  destructive,
  onConfirm,
  onCancel,
}: ConfirmProps) {
  const box = React.useRef<HTMLDivElement>(null);
  const id = React.useId();
  // Focus starts on the safe choice (the first button).
  React.useEffect(() => box.current?.querySelector("button")?.focus(), []);
  return (
    <div className="absolute inset-0 z-30 grid place-items-center bg-background/75 p-4 backdrop-blur-[2px]">
      <div
        ref={box}
        role="alertdialog"
        aria-modal="true"
        aria-labelledby={`${id}-t`}
        aria-describedby={`${id}-d`}
        className={cn("w-full max-w-sm border bg-popover p-4 text-popover-foreground shadow-lg", R)}
        onKeyDown={(event) => {
          if (event.key === "Escape") {
            event.stopPropagation();
            onCancel();
          }
        }}
      >
        <h3 id={`${id}-t`} className="text-sm font-medium">
          {title}
        </h3>
        <p id={`${id}-d`} className="mt-1 text-xs text-muted-foreground">
          {description}
        </p>
        <div className="mt-4 flex justify-end gap-2">
          <Button type="button" variant="outline" onClick={onCancel}>
            {cancelLabel}
          </Button>
          <Button
            type="button"
            variant={destructive ? "destructive" : "default"}
            onClick={onConfirm}
          >
            {confirmLabel}
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

// <FeedbaxLink />: a link to your portal that signs the visitor in first ("Go to feedbax").
import * as React from "react";

import { cn } from "@/lib/utils";
import {
  createTokenGetter,
  normalizePortalUrl,
  signInUrl,
  type GetToken,
} from "@/lib/feedbax/client";

export type FeedbaxLinkProps = Omit<React.ComponentProps<"a">, "href" | "target" | "onClick"> & {
  portalUrl: string;
  tokenUrl?: string;
  /** Overrides `tokenUrl`. */
  getToken?: () => Promise<{ token: string }>;
  /** Where to land: the board, or one post. Default "/". */
  to?: "/" | `/posts/${string}`;
  target?: "_self" | "_blank";
  children: React.ReactNode;
};

export function FeedbaxLink({
  portalUrl,
  tokenUrl,
  getToken,
  to = "/",
  target = "_self",
  className,
  children,
  ...anchorProps
}: FeedbaxLinkProps) {
  const fetchToken: GetToken = React.useMemo(
    () => getToken ?? createTokenGetter(tokenUrl),
    [getToken, tokenUrl],
  );
  const [pending, setPending] = React.useState(false);
  const fallback = normalizePortalUrl(portalUrl);

  const onClick = async (event: React.MouseEvent<HTMLAnchorElement>) => {
    // Let the browser handle modified clicks (open in new tab, etc.) with the plain portal link.
    if (
      event.defaultPrevented ||
      event.metaKey ||
      event.ctrlKey ||
      event.shiftKey ||
      event.altKey ||
      event.button !== 0
    )
      return;
    event.preventDefault();
    if (pending) return;
    setPending(true);
    // Open the window synchronously, inside the click, or popup blockers will stop it.
    const popup = target === "_blank" ? window.open("about:blank", "_blank") : null;
    if (popup) popup.opener = null;
    const go = (url: string) => (popup ? (popup.location.href = url) : window.location.assign(url));
    try {
      const { token } = await fetchToken();
      go(signInUrl({ portalUrl, token, to }));
    } catch {
      // The portal is public to read, so fall back to a plain visit instead of a dead end.
      go(fallback + (to === "/" ? "" : to));
    } finally {
      setPending(false);
    }
  };

  return (
    <a
      {...anchorProps}
      href={fallback}
      target={target}
      rel={target === "_blank" ? "noopener" : undefined}
      aria-busy={pending || undefined}
      onClick={onClick}
      className={cn(
        "text-primary underline-offset-4 hover:underline aria-busy:opacity-70",
        className,
      )}
    >
      {children}
    </a>
  );
}

// Pure canvas annotation engine: operations, command history, geometry and export. No React.
// Every coordinate is stored in SOURCE-image pixels, so replaying the operations on any canvas size
// (screen, HiDPI, export) draws the same picture.
import { LIMITS } from "./types";

export type Point = { x: number; y: number };
export type Operation =
  | { tool: "pen"; points: Point[]; color: string; width: number }
  | {
      tool: "arrow" | "rectangle" | "highlight" | "redact";
      from: Point;
      to: Point;
      color: string;
      width: number;
    };
export type Tool = Operation["tool"];

export const TOOLS: readonly Tool[] = ["pen", "arrow", "rectangle", "highlight", "redact"];
/** Accessible names, keyboard shortcuts and hints for the tools. The editor adds the icons. */
export const TOOL_INFO: Record<Tool, { label: string; key: string; hint: string }> = {
  pen: { label: "Pen", key: "P", hint: "Draw freehand." },
  arrow: { label: "Arrow", key: "A", hint: "Drag to point at something." },
  rectangle: { label: "Rectangle", key: "R", hint: "Drag to outline an area." },
  highlight: { label: "Highlight", key: "H", hint: "Drag to highlight an area." },
  redact: {
    label: "Hide sensitive info",
    key: "X",
    hint: "Drag over anything private. It is permanently covered in the image you send.",
  },
};

/** The tool a plain key press selects (P A R H X), or null. */
export function toolForKey(key: string): Tool | null {
  const upper = key.toUpperCase();
  return TOOLS.find((tool) => TOOL_INFO[tool].key === upper) ?? null;
}

export const MAX_OPERATIONS = 200;
export const MAX_PEN_POINTS = 1500;
export const HIGHLIGHT_ALPHA = 0.35;
/** Longest edge of the image we upload. The portal accepts 4096, this keeps files small. */
export const EXPORT_MAX_SIDE = 2560;

/* ------------------------------------------------------------------------------------------ *
 * Command history: immutable, replayable. `ops` is what is drawn, `undone` is the redo stack.
 * ------------------------------------------------------------------------------------------ */

export type History = { readonly ops: readonly Operation[]; readonly undone: readonly Operation[] };

export const emptyHistory: History = { ops: [], undone: [] };

export const canCommit = (h: History) => h.ops.length < MAX_OPERATIONS;
export const canUndo = (h: History) => h.ops.length > 0;
export const canRedo = (h: History) => h.undone.length > 0;

/** Adds an operation and drops the redo stack. At the operation limit the history is returned as is. */
export function commit(h: History, op: Operation): History {
  if (!canCommit(h)) return h;
  return { ops: [...h.ops, op], undone: [] };
}
export function undo(h: History): History {
  const last = h.ops[h.ops.length - 1];
  return last ? { ops: h.ops.slice(0, -1), undone: [...h.undone, last] } : h;
}
export function redo(h: History): History {
  const next = h.undone[h.undone.length - 1];
  return next ? { ops: [...h.ops, next], undone: h.undone.slice(0, -1) } : h;
}
export function clear(h: History): History {
  return h.ops.length === 0 && h.undone.length === 0 ? h : emptyHistory;
}

/* ------------------------------------------------------------------------------------------ *
 * Geometry
 * ------------------------------------------------------------------------------------------ */

export function normalizeRect(from: Point, to: Point) {
  const x = Math.min(from.x, to.x);
  const y = Math.min(from.y, to.y);
  return { x, y, width: Math.abs(to.x - from.x), height: Math.abs(to.y - from.y) };
}

/** Largest size with the source's aspect ratio that fits in the box (never upscales past 1:1 when `allowUpscale` is false). */
export function fitContain(
  srcW: number,
  srcH: number,
  maxW: number,
  maxH: number,
  allowUpscale = false,
) {
  if (srcW <= 0 || srcH <= 0 || maxW <= 0 || maxH <= 0) return { width: 0, height: 0 };
  const scale = Math.min(maxW / srcW, maxH / srcH, allowUpscale ? Infinity : 1);
  return {
    width: Math.max(1, Math.round(srcW * scale)),
    height: Math.max(1, Math.round(srcH * scale)),
  };
}

/** Backing-store size for a canvas that is `cssW × cssH` CSS pixels on a screen with this devicePixelRatio. */
export function backingSize(cssW: number, cssH: number, dpr: number) {
  const ratio = dpr > 0 ? dpr : 1;
  return {
    width: Math.max(1, Math.round(cssW * ratio)),
    height: Math.max(1, Math.round(cssH * ratio)),
  };
}

/** Maps a pointer position to source-image pixels. Independent of devicePixelRatio: only CSS geometry matters. */
export function pointerToSource(
  clientX: number,
  clientY: number,
  rect: { left: number; top: number; width: number; height: number },
  source: { width: number; height: number },
): Point {
  const x = ((clientX - rect.left) / rect.width) * source.width;
  const y = ((clientY - rect.top) / rect.height) * source.height;
  return {
    x: Math.min(source.width, Math.max(0, x)),
    y: Math.min(source.height, Math.max(0, y)),
  };
}

/** A stroke width that looks the same on a 800 px and a 4000 px image. */
export function defaultStrokeWidth(source: { width: number; height: number }): number {
  return Math.min(14, Math.max(3, Math.round(Math.max(source.width, source.height) / 320)));
}

const distance = (a: Point, b: Point) => Math.hypot(a.x - b.x, a.y - b.y);

function perpendicularDistance(p: Point, a: Point, b: Point): number {
  const length = distance(a, b);
  if (length === 0) return distance(p, a);
  return Math.abs((b.x - a.x) * (a.y - p.y) - (a.x - p.x) * (b.y - a.y)) / length;
}

/** Ramer–Douglas–Peucker, iterative so a long scribble cannot overflow the stack. */
export function simplifyPoints(points: readonly Point[], epsilon: number): Point[] {
  if (points.length <= 2) return points.slice();
  const keep = new Uint8Array(points.length);
  keep[0] = 1;
  keep[points.length - 1] = 1;
  const stack: Array<[number, number]> = [[0, points.length - 1]];
  while (stack.length > 0) {
    const [start, end] = stack.pop() as [number, number];
    let farthest = -1;
    let max = epsilon;
    for (let i = start + 1; i < end; i++) {
      const d = perpendicularDistance(points[i], points[start], points[end]);
      if (d > max) {
        max = d;
        farthest = i;
      }
    }
    if (farthest !== -1) {
      keep[farthest] = 1;
      stack.push([start, farthest], [farthest, end]);
    }
  }
  const result = points.filter((_, i) => keep[i] === 1);
  if (result.length <= MAX_PEN_POINTS) return result;
  const step = Math.ceil(result.length / MAX_PEN_POINTS);
  return result.filter((_, i) => i % step === 0 || i === result.length - 1);
}

/** Drops tap-sized shapes so a stray click never becomes an annotation. */
export function isMeaningful(op: Operation, minSize: number): boolean {
  if (op.tool === "pen") return op.points.length >= 2 || op.points.length === 1;
  return distance(op.from, op.to) >= minSize;
}

/* ------------------------------------------------------------------------------------------ *
 * Rendering
 * ------------------------------------------------------------------------------------------ */

type PenOperation = Extract<Operation, { tool: "pen" }>;

function drawPen(ctx: CanvasRenderingContext2D, op: PenOperation) {
  const { points } = op;
  if (points.length === 0) return;
  ctx.strokeStyle = op.color;
  ctx.fillStyle = op.color;
  ctx.lineWidth = op.width;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  if (points.length === 1) {
    ctx.beginPath();
    ctx.arc(points[0].x, points[0].y, op.width / 2, 0, Math.PI * 2);
    ctx.fill();
    return;
  }
  ctx.beginPath();
  ctx.moveTo(points[0].x, points[0].y);
  // Quadratic curves through the midpoints of consecutive points give a smooth line.
  for (let i = 1; i < points.length - 1; i++) {
    const mid = { x: (points[i].x + points[i + 1].x) / 2, y: (points[i].y + points[i + 1].y) / 2 };
    ctx.quadraticCurveTo(points[i].x, points[i].y, mid.x, mid.y);
  }
  const last = points[points.length - 1];
  ctx.lineTo(last.x, last.y);
  ctx.stroke();
}

type ShapeOperation = Exclude<Operation, { tool: "pen" }>;

function drawArrow(ctx: CanvasRenderingContext2D, op: ShapeOperation) {
  const { from, to } = op;
  const length = distance(from, to);
  if (length === 0) return;
  const ux = (to.x - from.x) / length;
  const uy = (to.y - from.y) / length;
  const head = Math.min(Math.max(op.width * 4.5, 14), length * 0.7);
  const baseX = to.x - ux * head * 0.8;
  const baseY = to.y - uy * head * 0.8;
  ctx.strokeStyle = op.color;
  ctx.fillStyle = op.color;
  ctx.lineWidth = op.width;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.beginPath();
  ctx.moveTo(from.x, from.y);
  ctx.lineTo(baseX, baseY);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(to.x, to.y);
  ctx.lineTo(to.x - ux * head + -uy * head * 0.45, to.y - uy * head + ux * head * 0.45);
  ctx.lineTo(to.x - ux * head - -uy * head * 0.45, to.y - uy * head - ux * head * 0.45);
  ctx.closePath();
  ctx.fill();
}

/** Draws operations in order. Safe to call repeatedly: every operation saves and restores the context. */
export function renderOperations(ctx: CanvasRenderingContext2D, ops: readonly Operation[]): void {
  for (const op of ops) {
    ctx.save();
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = "source-over";
    switch (op.tool) {
      case "pen":
        drawPen(ctx, op);
        break;
      case "arrow":
        drawArrow(ctx, op);
        break;
      case "rectangle": {
        const r = normalizeRect(op.from, op.to);
        ctx.strokeStyle = op.color;
        ctx.lineWidth = op.width;
        ctx.lineJoin = "round";
        ctx.strokeRect(r.x, r.y, r.width, r.height);
        break;
      }
      case "highlight": {
        const r = normalizeRect(op.from, op.to);
        ctx.globalAlpha = HIGHLIGHT_ALPHA;
        ctx.fillStyle = op.color;
        ctx.fillRect(r.x, r.y, r.width, r.height);
        break;
      }
      case "redact": {
        // Fully opaque: whatever was under this rectangle is gone from the flattened image.
        const r = normalizeRect(op.from, op.to);
        ctx.fillStyle = op.color;
        ctx.fillRect(r.x, r.y, r.width, r.height);
        break;
      }
    }
    ctx.restore();
  }
}

/** Draws the source bitmap and its operations scaled by `scale` (display pixels per source pixel). */
export function drawScene(
  ctx: CanvasRenderingContext2D,
  source: CanvasImageSource & { width: number; height: number },
  ops: readonly Operation[],
  scale: { x: number; y: number },
): void {
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, source.width * scale.x, source.height * scale.y);
  ctx.setTransform(scale.x, 0, 0, scale.y, 0, 0);
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = "high";
  ctx.drawImage(source, 0, 0);
  renderOperations(ctx, ops);
  ctx.restore();
}

/* ------------------------------------------------------------------------------------------ *
 * Export: flatten once, encode once. Only these pixels ever leave the browser.
 * ------------------------------------------------------------------------------------------ */

export type CanvasLike = HTMLCanvasElement | OffscreenCanvas;
export type ExportOptions = {
  maxSide?: number;
  maxBytes?: number;
  createCanvas?: (width: number, height: number) => CanvasLike;
};

export function createCanvas(width: number, height: number): CanvasLike {
  if (typeof OffscreenCanvas !== "undefined") return new OffscreenCanvas(width, height);
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  return canvas;
}

export function canvasToBlob(
  canvas: CanvasLike,
  type: string,
  quality?: number,
): Promise<Blob | null> {
  if ("convertToBlob" in canvas) return canvas.convertToBlob({ type, quality }).catch(() => null);
  return new Promise((resolve) => (canvas as HTMLCanvasElement).toBlob(resolve, type, quality));
}

/** Draws the source and every operation onto a fresh canvas of the given size. */
export function flatten(
  source: { width: number; height: number } & CanvasImageSource,
  ops: readonly Operation[],
  width: number,
  height: number,
  make: (w: number, h: number) => CanvasLike = createCanvas,
): CanvasLike {
  const canvas = make(width, height);
  const ctx = canvas.getContext("2d") as CanvasRenderingContext2D | null;
  if (!ctx) throw new Error("Canvas 2D is not available in this browser.");
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = "high";
  ctx.drawImage(source, 0, 0, width, height);
  ctx.save();
  ctx.scale(width / source.width, height / source.height);
  renderOperations(ctx, ops);
  ctx.restore();
  return canvas;
}

/**
 * Flattens the picture and its operations into one PNG (WebP when a PNG would be over 5 MiB).
 * The bitmap and the operation list stay in the browser. Redact rectangles are plain opaque pixels here.
 */
export async function exportImage(
  source: ImageBitmap,
  ops: readonly Operation[],
  options: ExportOptions = {},
): Promise<Blob> {
  const maxSide = options.maxSide ?? EXPORT_MAX_SIDE;
  const maxBytes = options.maxBytes ?? LIMITS.imageBytes;
  const make = options.createCanvas ?? createCanvas;
  let shrink = Math.min(1, maxSide / Math.max(source.width, source.height));

  for (let round = 0; round < 5; round++) {
    const width = Math.max(1, Math.round(source.width * shrink));
    const height = Math.max(1, Math.round(source.height * shrink));
    const canvas = flatten(source, ops, width, height, make);
    const png = await canvasToBlob(canvas, "image/png");
    if (png && png.type === "image/png" && png.size <= maxBytes) return png;
    for (const quality of [0.92, 0.8, 0.65]) {
      const webp = await canvasToBlob(canvas, "image/webp", quality);
      if (webp && webp.type === "image/webp" && webp.size <= maxBytes) return webp;
    }
    shrink *= 0.75;
  }
  throw new Error("This image is too large to send. Try a smaller screenshot.");
}

/* ------------------------------------------------------------------------------------------ *
 * Theme colours
 * ------------------------------------------------------------------------------------------ */

/** Converts any CSS colour the browser understands (oklch, hsl, rgb, …) to an opaque `rgb()` string. */
export function resolveCssColor(
  css: string,
): { rgb: string; r: number; g: number; b: number; a: number } | null {
  const canvas = createCanvas(1, 1);
  const ctx = canvas.getContext("2d", {
    willReadFrequently: true,
  }) as CanvasRenderingContext2D | null;
  if (!ctx) return null;
  ctx.clearRect(0, 0, 1, 1);
  ctx.fillStyle = "#000";
  ctx.fillStyle = css;
  ctx.fillRect(0, 0, 1, 1);
  const [r, g, b, a] = ctx.getImageData(0, 0, 1, 1).data;
  return { rgb: `rgb(${r}, ${g}, ${b})`, r, g, b, a };
}

// Screenshot capture. Browser only; `modern-screenshot` is loaded lazily so SSR and first paint stay light.
export const IGNORE_ATTRIBUTE = "data-feedbax-ignore";

export class CaptureCancelledError extends Error {
  constructor() {
    super("Capture was cancelled.");
    this.name = "CaptureCancelledError";
  }
}
export class CaptureError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "CaptureError";
  }
}

export const canCaptureScreen = (): boolean =>
  typeof navigator !== "undefined" && typeof navigator.mediaDevices?.getDisplayMedia === "function";

const nextFrame = () => new Promise<void>((resolve) => requestAnimationFrame(() => resolve()));
const wait = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

/** Resolves once the given element is no longer in the document (or after `timeout` ms). */
export async function waitUntilGone(selector: string, timeout = 1200): Promise<void> {
  const start = performance.now();
  while (document.querySelector(selector) && performance.now() - start < timeout) await wait(30);
  await nextFrame();
  await nextFrame();
}

function pageBackground(): string {
  for (const el of [document.body, document.documentElement]) {
    const color = getComputedStyle(el).backgroundColor;
    if (color && color !== "rgba(0, 0, 0, 0)" && color !== "transparent") return color;
  }
  return "white";
}

/** Nodes the snapshot leaves out: anything marked `data-feedbax-ignore`, and the dialog overlay. */
export const isIgnored = (node: Node): boolean =>
  node instanceof Element &&
  (node.hasAttribute(IGNORE_ATTRIBUTE) || node.getAttribute("data-slot") === "dialog-overlay");

/**
 * Captures what the user currently sees: the visible viewport of this page, as a PNG.
 * Elements marked `data-feedbax-ignore` (the dialog, its overlay, anything the host marks) are left out.
 * Known limits: cross-origin images without CORS, iframes, video frames and some CSS effects.
 */
export async function captureViewport(): Promise<Blob> {
  const { domToBlob } = await import("modern-screenshot");
  const root = document.documentElement;
  const scrollX = window.scrollX;
  const scrollY = window.scrollY;

  // `position: fixed` elements are re-anchored by the library's scroll restoration. We remember the
  // originals in clone order (filter runs pre-order, onCloneEachNode post-order, so a stack lines up)
  // and move them back to where they are on screen.
  const stack: Array<Element | null> = [];
  const filter = (node: Node): boolean => {
    if (isIgnored(node)) return false;
    if (node.nodeType === Node.TEXT_NODE) return true; // text nodes never reach onCloneEachNode
    stack.push(
      (scrollX || scrollY) && node instanceof Element && getComputedStyle(node).position === "fixed"
        ? node
        : null,
    );
    return true;
  };
  const onCloneEachNode = (cloned: Node) => {
    const original = stack.pop();
    if (original && cloned instanceof HTMLElement && original.localName === cloned.localName)
      cloned.style.setProperty("translate", `${scrollX}px ${scrollY}px`);
  };

  try {
    return await domToBlob(root, {
      width: root.clientWidth,
      height: window.innerHeight,
      scale: Math.min(window.devicePixelRatio || 1, 2),
      type: "image/png",
      backgroundColor: pageBackground(),
      filter,
      onCloneEachNode,
      features: { restoreScrollPosition: true },
      timeout: 15_000,
    });
  } catch (error) {
    throw new CaptureError(
      error instanceof Error ? error.message : "The page could not be captured.",
    );
  }
}

/**
 * Captures a frame of the screen (or tab) through the browser's own picker.
 * `beforeFrame` runs after the user has chosen what to share and before the frame is read:
 * the dialog hides itself there so it is not part of the picture. Every track is always stopped.
 */
export async function captureScreen(
  options: { beforeFrame?: () => Promise<void> } = {},
): Promise<Blob> {
  if (!canCaptureScreen())
    throw new CaptureError("Screen capture is not available in this browser.");
  let stream: MediaStream;
  try {
    stream = await navigator.mediaDevices.getDisplayMedia({
      video: true,
      audio: false,
      preferCurrentTab: true,
    } as DisplayMediaStreamOptions);
  } catch (error) {
    if (
      error instanceof DOMException &&
      (error.name === "NotAllowedError" || error.name === "AbortError")
    )
      throw new CaptureCancelledError();
    throw new CaptureError("Screen capture could not start.");
  }

  const video = document.createElement("video");
  try {
    video.muted = true;
    video.playsInline = true;
    video.srcObject = stream;
    await new Promise<void>((resolve, reject) => {
      video.onloadedmetadata = () => resolve();
      video.onerror = () => reject(new CaptureError("Screen capture could not start."));
    });
    await video.play();
    await options.beforeFrame?.();
    // Give the compositor time to deliver a frame that no longer contains the dialog.
    await wait(250);
    if ("requestVideoFrameCallback" in video)
      await new Promise<void>((resolve) => video.requestVideoFrameCallback(() => resolve()));
    if (stream.getVideoTracks().every((track) => track.readyState === "ended"))
      throw new CaptureCancelledError();

    const canvas = document.createElement("canvas");
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext("2d");
    if (!ctx || canvas.width === 0)
      throw new CaptureError("Screen capture returned an empty frame.");
    ctx.drawImage(video, 0, 0);
    const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, "image/png"));
    if (!blob) throw new CaptureError("Screen capture returned an empty frame.");
    return blob;
  } finally {
    for (const track of stream.getTracks()) track.stop();
    video.srcObject = null;
  }
}

// Browser-side API client for the Feedbax portal. No dependencies, no React.
import type { ApiError, Category, CreatePostResult, ErrorCode, TokenResult } from "./types";

export type GetToken = () => Promise<TokenResult>;

export type FeedbaxErrorKind =
  | "token" // your token endpoint failed: usually the user is signed out of your app
  | "network" // the portal could not be reached (offline, CORS, DNS)
  | "api"; // the portal answered with an error

/** Everything the dialog needs to explain a failure and decide whether a retry makes sense. */
export class FeedbaxError extends Error {
  readonly kind: FeedbaxErrorKind;
  readonly code: ErrorCode | null;
  readonly status: number | null;
  readonly field: string | null;
  readonly retryAfterSeconds: number | null;
  constructor(
    kind: FeedbaxErrorKind,
    message: string,
    extra: {
      code?: ErrorCode | null;
      status?: number | null;
      field?: string | null;
      retryAfterSeconds?: number | null;
    } = {},
  ) {
    super(message);
    this.name = "FeedbaxError";
    this.kind = kind;
    this.code = extra.code ?? null;
    this.status = extra.status ?? null;
    this.field = extra.field ?? null;
    this.retryAfterSeconds = extra.retryAfterSeconds ?? null;
  }
}

/** Removes a trailing slash and refuses anything that is not an http(s) URL. */
export function normalizePortalUrl(portalUrl: string): string {
  let url: URL;
  try {
    url = new URL(portalUrl);
  } catch {
    throw new Error(`Invalid portalUrl: ${portalUrl}`);
  }
  if (url.protocol !== "https:" && url.protocol !== "http:")
    throw new Error("portalUrl must be http(s)");
  return url.origin + url.pathname.replace(/\/+$/, "");
}

/** Fetches a fresh single-use token from the host's own endpoint (same-origin cookies). */
export function createTokenGetter(tokenUrl = "/api/feedbax-token"): GetToken {
  return async () => {
    let response: Response;
    try {
      response = await fetch(tokenUrl, {
        method: "POST",
        credentials: "same-origin",
        cache: "no-store",
        headers: { Accept: "application/json" },
      });
    } catch {
      throw new FeedbaxError("token", "Could not reach this app's feedback endpoint.");
    }
    if (!response.ok) {
      throw new FeedbaxError(
        "token",
        response.status === 401 || response.status === 403
          ? "You need to be signed in to send feedback."
          : "Could not get permission to send feedback.",
        { status: response.status },
      );
    }
    const data = (await response.json().catch(() => null)) as Partial<TokenResult> | null;
    if (!data || typeof data.token !== "string" || data.token.length === 0)
      throw new FeedbaxError("token", "The feedback endpoint returned an unexpected response.", {
        status: response.status,
      });
    return { token: data.token };
  };
}

const SAFE_TO = /^(\/|\/posts\/[0-9a-fA-F-]{36})$/;

/** The SSO link that signs the user in to the portal and lands on `to` ("/" or "/posts/<id>"). */
export function signInUrl({
  portalUrl,
  token,
  to = "/",
}: {
  portalUrl: string;
  token: string;
  to?: string;
}): string {
  const target = SAFE_TO.test(to) ? to : "/";
  const query = new URLSearchParams({ token, to: target });
  return `${normalizePortalUrl(portalUrl)}/api/auth/feedbax/sign-in?${query.toString()}`;
}

async function readApiError(response: Response): Promise<FeedbaxError> {
  const body = (await response.json().catch(() => null)) as { error?: Partial<ApiError> } | null;
  const retryAfter = Number(response.headers.get("Retry-After"));
  return new FeedbaxError(
    "api",
    body?.error?.message ?? `The portal returned ${response.status}.`,
    {
      code: body?.error?.code ?? null,
      status: response.status,
      field: body?.error?.field ?? null,
      retryAfterSeconds: Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter : null,
    },
  );
}

export type SubmitFeedbackOptions = {
  portalUrl: string;
  getToken: GetToken;
  id: string;
  title: string;
  body: string;
  category: Category;
  images: Blob[];
  signal?: AbortSignal;
};

/**
 * One multipart POST to `{portalUrl}/api/posts`. Cross-origin, `credentials: 'omit'`, bearer token.
 * A 401 means the single-use token was rejected, so we fetch one more token and retry once.
 * The post `id` never changes here, which makes the retry safe (the portal treats a replay as a no-op).
 */
export async function submitFeedback(o: SubmitFeedbackOptions): Promise<CreatePostResult> {
  o.signal?.throwIfAborted();
  const endpoint = `${normalizePortalUrl(o.portalUrl)}/api/posts`;
  const form = new FormData();
  form.set("id", o.id);
  form.set("title", o.title);
  form.set("body", o.body);
  form.set("category", o.category);
  o.images.forEach((image, index) => {
    const extension =
      image.type === "image/webp" ? "webp" : image.type === "image/jpeg" ? "jpg" : "png";
    form.append("image", image, `image-${index + 1}.${extension}`);
  });

  const attempt = async (): Promise<Response> => {
    o.signal?.throwIfAborted();
    const { token } = await o.getToken();
    o.signal?.throwIfAborted();
    try {
      return await fetch(endpoint, {
        method: "POST",
        body: form,
        headers: { Authorization: `Bearer ${token}` },
        credentials: "omit",
        mode: "cors",
        signal: o.signal,
      });
    } catch (error) {
      if (error instanceof DOMException && error.name === "AbortError") throw error;
      throw new FeedbaxError("network", "Could not reach the feedback portal.");
    }
  };

  let response = await attempt();
  if (response.status === 401) response = await attempt();
  if (!response.ok) throw await readApiError(response);
  const data = (await response.json().catch(() => null)) as Partial<CreatePostResult> | null;
  if (!data || typeof data.postId !== "string")
    throw new FeedbaxError("api", "The portal returned an unexpected response.", {
      status: response.status,
    });
  return { postId: data.postId, postUrl: typeof data.postUrl === "string" ? data.postUrl : "" };
}

export type ErrorView = {
  message: string;
  /** The form field to point at, when the portal told us which one is wrong. */
  field: "title" | "body" | "category" | "image" | null;
  /** Retrying the same draft can succeed. When false, the user has to change something first. */
  retryable: boolean;
};

function waitText(seconds: number | null): string {
  if (!seconds) return "a little while";
  if (seconds < 90) return "a minute";
  return `${Math.ceil(seconds / 60)} minutes`;
}

/** Turns any failure from `submitFeedback` into copy a person can act on. */
export function describeSubmitError(error: unknown): ErrorView {
  if (!(error instanceof FeedbaxError))
    return {
      message: "Something went wrong. Your draft is safe, so you can try again.",
      field: null,
      retryable: true,
    };

  if (error.kind === "token") {
    return {
      message:
        error.status === 401 || error.status === 403
          ? "You need to be signed in to send feedback. Sign in to this app, then try again."
          : "We couldn't get permission to send feedback just now. Try again in a moment.",
      field: null,
      retryable: true,
    };
  }
  if (error.kind === "network") {
    return {
      message:
        "We couldn't reach the feedback portal. Check your connection and try again. If it keeps happening, the portal may not allow this site yet (see appUrl in its settings).",
      field: null,
      retryable: true,
    };
  }
  const field =
    (["title", "body", "category"] as const).find((name) => name === error.field) ??
    (error.field === "image" ? "image" : null);
  switch (error.code) {
    case "unauthenticated":
      return {
        message: "The portal didn't accept your sign-in. Reload this page and try again.",
        field: null,
        retryable: true,
      };
    case "rate_limited":
      return {
        message: `You've sent a lot of feedback recently. Please try again in ${waitText(error.retryAfterSeconds)}.`,
        field: null,
        retryable: true,
      };
    case "too_large":
    case "unsupported_image":
      return {
        message:
          "One of your images is too large or isn't a PNG, JPEG or WebP. Remove or replace it, then send again.",
        field: "image",
        retryable: false,
      };
    case "invalid_input":
      return { message: error.message, field, retryable: false };
    case "conflict":
      return {
        message: "We couldn't send this draft. Change something and send it again.",
        field: null,
        retryable: false,
      };
    case "forbidden":
      return {
        message: "This site isn't allowed to send feedback to the portal.",
        field: null,
        retryable: false,
      };
    default:
      return {
        message: "The feedback portal is having trouble right now. Try again in a minute.",
        field: null,
        retryable: true,
      };
  }
}

// The feedback draft as a pure reducer, so id and retry rules can be tested without a DOM.
import type { Category } from "./types";

export type Draft<A> = {
  /** Client-generated post id: the portal's idempotency key. */
  id: string;
  title: string;
  body: string;
  category: Category | null;
  attachments: A[];
  /** A submit failed with this draft. Editing it now starts a new post id. */
  failed: boolean;
};

export type DraftAction<A extends { id: string }> =
  | { type: "title"; value: string }
  | { type: "body"; value: string }
  | { type: "category"; value: Category }
  | { type: "attach"; attachment: A }
  | { type: "replace"; id: string; attachment: A }
  | { type: "update"; id: string; attachment: A }
  | { type: "remove"; id: string }
  | { type: "failed" }
  | { type: "reset"; id: string };

export function uuid(): string {
  if (typeof crypto.randomUUID === "function") return crypto.randomUUID();
  const b = crypto.getRandomValues(new Uint8Array(16));
  b[6] = (b[6] & 0x0f) | 0x40;
  b[8] = (b[8] & 0x3f) | 0x80;
  const h = Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
}

export const emptyDraft = <A>(id: string): Draft<A> => ({
  id,
  title: "",
  body: "",
  category: null,
  attachments: [],
  failed: false,
});

export const hasContent = <A>(d: Draft<A>) =>
  d.title.trim() !== "" || d.body.trim() !== "" || d.attachments.length > 0;

export function draftReducer<A extends { id: string }>(
  state: Draft<A>,
  action: DraftAction<A>,
  newId: () => string = uuid,
): Draft<A> {
  if (action.type === "reset") return emptyDraft(action.id);
  if (action.type === "failed") return { ...state, failed: true };
  // Any other action edits the draft. After a failed submit that means a new post id.
  const base: Draft<A> = state.failed ? { ...state, id: newId(), failed: false } : state;
  switch (action.type) {
    case "title":
      return { ...base, title: action.value };
    case "body":
      return { ...base, body: action.value };
    case "category":
      return { ...base, category: action.value };
    case "attach":
      return { ...base, attachments: [...base.attachments, action.attachment] };
    case "replace":
    case "update":
      return {
        ...base,
        attachments: base.attachments.map((a) => (a.id === action.id ? action.attachment : a)),
      };
    case "remove":
      return { ...base, attachments: base.attachments.filter((a) => a.id !== action.id) };
  }
}

// Decoding and size limits for attached images. Browser only.
import { LIMITS } from "./types";

export const ACCEPT_ATTRIBUTE = "image/png,image/jpeg,image/webp";
export type AcceptedMime = "image/png" | "image/jpeg" | "image/webp";

export class ImageError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ImageError";
  }
}

/** Reads the magic bytes: the declared MIME type of a pasted or dropped file is not always right. */
export async function sniffImageType(blob: Blob): Promise<AcceptedMime | null> {
  const head = new Uint8Array(await blob.slice(0, 12).arrayBuffer());
  if (head[0] === 0x89 && head[1] === 0x50 && head[2] === 0x4e && head[3] === 0x47)
    return "image/png";
  if (head[0] === 0xff && head[1] === 0xd8 && head[2] === 0xff) return "image/jpeg";
  const riff = String.fromCharCode(...head.slice(0, 4)) === "RIFF";
  if (riff && String.fromCharCode(...head.slice(8, 12)) === "WEBP") return "image/webp";
  return null;
}

/** Largest size within 4096 px per side and 16 megapixels, keeping the aspect ratio. */
export function limitSize(width: number, height: number) {
  const scale = Math.min(
    1,
    LIMITS.imageSide / Math.max(width, height),
    Math.sqrt(LIMITS.imagePixels / (width * height)),
  );
  return scale >= 1
    ? { width, height, scaled: false }
    : {
        width: Math.max(1, Math.floor(width * scale)),
        height: Math.max(1, Math.floor(height * scale)),
        scaled: true,
      };
}

/** Decodes a PNG/JPEG/WebP file to a bitmap, honouring EXIF rotation and downscaling oversized images. */
export async function decodeImage(blob: Blob): Promise<ImageBitmap> {
  if (!(await sniffImageType(blob))) throw new ImageError("Use a PNG, JPEG or WebP image.");
  let bitmap: ImageBitmap;
  try {
    bitmap = await createImageBitmap(blob, { imageOrientation: "from-image" });
  } catch {
    throw new ImageError("That image could not be read. Try another file.");
  }
  const size = limitSize(bitmap.width, bitmap.height);
  if (!size.scaled) return bitmap;
  const resized = await createImageBitmap(bitmap, {
    resizeWidth: size.width,
    resizeHeight: size.height,
    resizeQuality: "high",
  });
  bitmap.close();
  return resized;
}

/** Image files from a paste or drop event, in order. */
export function imageFilesFrom(items: DataTransfer | null): File[] {
  if (!items) return [];
  const files = Array.from(items.files).filter((file) => file.type.startsWith("image/"));
  if (files.length > 0) return files;
  return Array.from(items.items ?? [])
    .filter((item) => item.kind === "file" && item.type.startsWith("image/"))
    .map((item) => item.getAsFile())
    .filter((file): file is File => file !== null);
}

// SERVER ONLY. Never import this file from client code: it needs your FEEDBAX_HOST_SECRET.
// Mints the single-use, 5-minute HS256 JWT that the Feedbax block sends to your portal.
// Web Crypto only, no dependencies: it runs on Node 20+, Bun, Deno and Cloudflare Workers.
import { HOST_TOKEN_HEADER, HOST_TOKEN_TTL_SECONDS, type MintOptions } from "./types";

const encoder = new TextEncoder();

function base64url(bytes: Uint8Array): string {
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function decodeSecret(secret: string): Uint8Array {
  if (typeof secret !== "string" || !/^[A-Za-z0-9_-]+$/.test(secret) || secret.length % 4 === 1)
    throw new Error("FEEDBAX_HOST_SECRET must be base64url text");
  const standard = secret.replace(/-/g, "+").replace(/_/g, "/");
  const bytes = Uint8Array.from(
    atob(standard.padEnd(Math.ceil(standard.length / 4) * 4, "=")),
    (c) => c.charCodeAt(0),
  );
  if (base64url(bytes) !== secret)
    throw new Error("FEEDBAX_HOST_SECRET must be canonical base64url text");
  return bytes;
}

/** Returns a compact JWT for the signed-in host user. Call it once per request from your own session. */
export async function mintFeedbaxToken({ secret, user, now, jti }: MintOptions): Promise<string> {
  const keyBytes = decodeSecret(secret);
  if (keyBytes.length < 32) throw new Error("FEEDBAX_HOST_SECRET is too short");
  if (
    typeof user.id !== "string" ||
    !user.id.trim() ||
    Array.from(user.id).length > 200 ||
    /[\r\n\u2028\u2029]/u.test(user.id)
  )
    throw new Error("user.id must be 1-200 characters without a newline");
  if (typeof user.name !== "string" || !user.name.trim() || Array.from(user.name).length > 80)
    throw new Error("user.name must be 1-80 characters");

  const iat = now ?? Math.floor(Date.now() / 1000);
  const payload = {
    sub: user.id,
    name: user.name,
    exp: iat + HOST_TOKEN_TTL_SECONDS,
    jti: jti ?? crypto.randomUUID(),
  };
  const signingInput = `${base64url(encoder.encode(HOST_TOKEN_HEADER))}.${base64url(encoder.encode(JSON.stringify(payload)))}`;
  const key = await crypto.subtle.importKey(
    "raw",
    keyBytes as BufferSource,
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const signature = await crypto.subtle.sign("HMAC", key, encoder.encode(signingInput));
  return `${signingInput}.${base64url(new Uint8Array(signature))}`;
}

